      throw new Error('Set operation value must be a string');
    }
    return mapValues(base, (v, k) => {
      if (k === key) {
        return value;
      }
      return v;
    });
  }

  if (operation === 'unset') {
    if (key === undefined || key === null) {
      throw new Error('Unset operation requires a key');
    }
    if (typeof key !== 'string' || key.length === 0) {
      throw new Error('Unset operation key must be a non-empty string');
    }
    return mapValues(base, (v, k) => {
      if (k === key) {
        return undefined;
      }
      return v;
    });
  }

  if (operation === 'remove') {
    if (key === undefined || key === null) {
      throw new Error('Remove operation requires a key');
    }
    if (typeof key !== 'string' || key.length === 0) {
      throw new Error('Remove operation key must be a non-empty string');
    }
    return mapValues(base, (v, k) => {
      if (k === key) {
        return undefined;
      }
      return v;
    });
  }

  throw new Error(`Unknown operation: ${operation}`);
}

function patchConfig(base, patches) {
  if (!Array.isArray(patches)) {
    throw new Error('Patches must be an array');
  }

  const result = mapValues(base, (v, k) => {
    if (typeof v !== 'string') {
      throw new Error(`Base configuration value for key "${k}" is not a string`);
    }
    return v;
  });

  for (const patch of patches) {
    try {
      result = applyPatch(result, patch);
    } catch (err) {
      throw err;
    }
  }

  return result;
}

module.exports = {
  patchConfig
};

